    "key_findings": [
      {
        "claim": "Seeing the ad alone lowered Democrats’ ratings of people with criminal records by 0.835 standard deviations compared with answering before seeing it.",
        "quotes": [
          {
            "text": "exposure to the Trump advertisement alone significantly decreased positive perceptions of individuals with criminal records ( β̂0 = −0.835, SE = 0.044)",
            "page": 11
          }
        ]
      },
      {
        "claim": "Hearing Jackson’s perspective before seeing the ad raised ratings of people with criminal records by about 0.83 standard deviations compared with seeing the ad alone, nearly offsetting the ad’s negative effect.",
        "quotes": [
          {
            "text": "exposure to the counter-narrative prior to being presented with the Trump advertisement increased positive perceptions of individuals with criminal records by more than 0.8 standard deviation (SD) units, compared to those\npresented with the Trump advertisement alone ( β̂2 = 0.83, SE = 0.041).",
            "page": 11
          }
        ]
      },
      {
        "claim": "The ad improved perceived representation, whereas hearing the counter-narrative first lowered ratings of federal Democratic representation compared with the ad alone. The ad also increased perceived public-service motives, but that finding did not survive the reported multiple-comparisons correction.",
